const within = `-- name: Within :one
WITH RECURSIVE up AS (
    SELECT o.id, o.parent_id FROM iam.org_units o WHERE o.id = $2
    UNION
    SELECT o.id, o.parent_id FROM iam.org_units o JOIN up ON o.id = up.parent_id
)
SELECT EXISTS (SELECT 1 FROM up WHERE up.id = $1::bigint)
`

type WithinParams struct {
	Ancestor int64
	Unit     int64
}

// Whether @unit is @ancestor or below it.
func (q *Queries) Within(ctx context.Context, arg WithinParams) (bool, error) {
	row := q.db.QueryRow(ctx, within, arg.Ancestor, arg.Unit)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
